python3 -c "
import itertools
def revcomp(s):
    return ''.join({'G':'C','C':'G','A':'U','U':'A'}[c] for c in reversed(s))
bases='GCAU'
pals=[]
for combo in itertools.product(bases, repeat=5):
    first=''.join(combo)
    s=first+revcomp(first)
    if not any(x*4 in s for x in 'GCAU'):
        pals.append(s)
print('pals:', len(pals))
def max_common(a,b):
    m=0
    for i in range(len(a)):
        for j in range(len(b)):
            k=0
            while i+k<len(a) and j+k<len(b) and a[i+k]==b[j+k]:
                k+=1
            m=max(m,k)
    return m
# greedy select 7 palindromes pairwise with max_common(s_i, revcomp(s_j)) small
# since palindromic, revcomp(s_j)=s_j. So check max_common(s_i,s_j) small (means few contiguous matches -> fewer cross pairs)
# But cross-pairing is s_i pairs with s_j means s_i == revcomp(s_j) region. For palindrome s_j==revcomp(s_j), so cross pairing ~ max_common(s_i, s_j).
# We want diverse: low mutual common substring.
import random
random.seed(1)
selected=[]
pool=list(pals)
random.shuffle(pool)
for p in pool:
    ok=True
    for q in selected:
        if max_common(p,q)>=5:
            ok=False; break
    if ok:
        selected.append(p)
    if len(selected)>=7: break
for s in selected:
    print(s, len(s))
"

